WITH scope AS (SELECT * FROM entities WHERE eid>=49 AND eid<61),
events_visible AS (SELECT e.*,s.region,s.sector,c.weekday,c.offset_min,minute+c.offset_min civil_min FROM events e JOIN scope s ON s.eid=e.eid JOIN calendar c ON c.day=e.day WHERE e.day>=10 AND e.day<78 AND received_min<=28517760),
ev AS (SELECT *,CAST(magnitude AS DOUBLE) x,ROW_NUMBER() OVER(PARTITION BY eid ORDER BY minute,event_id) rn,LAG(minute) OVER(PARTITION BY eid ORDER BY minute,event_id) prev_min,LAG(kind) OVER(PARTITION BY eid ORDER BY minute,event_id) prev_kind FROM events_visible),
a AS (SELECT *,CASE WHEN prev_min IS NULL OR minute-prev_min>2200 THEN 1 ELSE 0 END boundary FROM ev),
b AS (SELECT *,SUM(boundary) OVER(PARTITION BY eid ORDER BY minute,event_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) session_id FROM a),
c AS (SELECT *,FIRST_VALUE(minute) OVER(PARTITION BY eid,session_id ORDER BY minute,event_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_min,LAST_VALUE(minute) OVER(PARTITION BY eid,session_id ORDER BY minute,event_id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) last_min,SUM(x) OVER(PARTITION BY eid,session_id ORDER BY minute,event_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative,MIN(CASE WHEN kind=0 THEN minute ELSE NULL END) OVER(PARTITION BY eid,session_id ORDER BY minute,event_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_phase0,MIN(CASE WHEN kind=1 THEN minute ELSE NULL END) OVER(PARTITION BY eid,session_id ORDER BY minute,event_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_phase1,ROW_NUMBER() OVER(PARTITION BY eid,session_id ORDER BY minute,event_id) session_rank FROM b)
SELECT eid,minute,event_id,x,rn,session_id,first_min,last_min,cumulative,first_phase0,first_phase1,session_rank FROM c WHERE day>=30 ORDER BY eid,minute,event_id;
